import fs from 'node:fs';
import {pathToFileURL} from 'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));
const {McpHost}=await import(new URL('host.js',base));
const {DeterministicLiveSimulator}=await import(new URL('live.js',base));
const init={jsonrpc:'2.0',id:'setup',method:'initialize',params:{protocolVersion:'2025-11-25',capabilities:{},clientInfo:{name:'oracle',version:'1'}}};
const meta={'io.modelcontextprotocol/protocolVersion':'2026-07-28','io.modelcontextprotocol/clientCapabilities':{}};
const clean=value=>{
 if(typeof value==='string'&&/^(trackstruct|transportaction|devdel|clipdel|scenedel|trackdel|locatordel|arrmidi|data|browserload|devdup|device|mixer|tempo|parameter|parameters|structure|arrangement|rename|transport|change|noteupdate|notedelete|routing|capturemidi|scenecapture|clipdup|arrclip|clipmove)_[A-Za-z0-9_-]+$/.test(value))return value.split('_')[0]+'_<id>';
 if(Array.isArray(value))return value.map(clean);
 if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,v])=>[key,['expiresAt','sampledAt'].includes(key)?'<time>':key==='text'&&typeof v==='string'?(()=>{try{return clean(JSON.parse(v))}catch{return v}})():clean(v)]));
 return value;
};
const cases=[];
async function run(label,operations,{modern=false,sync=false,policy}={}){
 const sim=new DeterministicLiveSimulator(),host=new McpHost(sim,{...(policy?{toolPolicy:policy}:{})}),results=[];let tx,seq=0;
 if(!modern){host.handle(init);host.handle({jsonrpc:'2.0',method:'notifications/initialized'});}
 for(const op of operations){
  if(op.policy){host.setToolPolicy(op.policy);results.push({policy:true});continue;}
  const args=JSON.parse(JSON.stringify(Object.hasOwn(op,'args')?op.args:{}).replaceAll('"$tx"',JSON.stringify(tx??'missing')));
  const request={jsonrpc:'2.0',id:++seq,method:'tools/call',params:{name:op.tool,arguments:args,...(modern?{_meta:meta}:{})}};
  const controller=new AbortController();if(op.abort)controller.abort();
  try{const result=sync?host.handle(request):await host.handleAsync(request,controller.signal);results.push(clean(result));
   try{const body=JSON.parse(result.result.content[0].text);if(body.transactionId)tx=body.transactionId}catch{}
  }catch(e){results.push({error:e.message});}
 }
 cases.push({label,operations,modern,sync,...(policy?{policy}:{}),results,state:clean(sim.state)});
}
const tools=['live_automation_preview','live_automation_apply','live_transport_action_preview','live_transport_action_apply','live_track_structure_preview','live_track_structure_apply','live_device_delete_preview','live_device_delete_apply','live_clip_delete_preview','live_clip_delete_apply','live_scene_delete_preview','live_scene_delete_apply','live_track_delete_preview','live_track_delete_apply','live_locator_delete_preview','live_locator_delete_apply','live_application_dialog_preview','live_application_dialog_apply','live_clip_view_preview','live_clip_view_apply','live_device_view_preview','live_device_view_apply','live_selection_preview','live_selection_apply','live_warp_marker_preview','live_warp_marker_apply','live_clip_action_preview','live_clip_action_apply','live_drum_pad_preview','live_drum_pad_apply','live_device_edit_preview','live_device_edit_apply','live_rack_preview','live_rack_apply','live_rack_view_preview','live_rack_view_apply','live_scene_preview','live_scene_apply','live_scene_fire_preview','live_scene_fire_apply','live_track_view_preview','live_track_view_apply','live_track_properties_preview','live_track_properties_apply','live_song_settings_preview','live_song_settings_apply','live_arrangement_midi_clip_preview','live_arrangement_midi_clip_apply','live_clip_clear_range_preview','live_clip_clear_range_apply','live_fire_button_preview','live_fire_button_apply','live_device_specialized_preview','live_device_specialized_apply','live_looper_preview','live_looper_apply','live_groove_preview','live_groove_apply','live_tuning_preview','live_tuning_apply','live_simpler_preview','live_simpler_apply','live_midi_transform_preview','live_midi_transform_apply','live_device_advanced_preview','live_device_advanced_apply','live_chain_preview','live_chain_apply','live_willington_device_preview','live_willington_device_apply','live_data_preview','live_data_apply','live_follow_actions_preview','live_follow_actions_apply','live_clip_properties_preview','live_clip_properties_apply','live_mixer_extended_preview','live_mixer_extended_apply','live_chain_mixer_preview','live_chain_mixer_apply','live_device_io_preview','live_device_io_apply','live_device_preview','live_device_apply','live_audio_import_preview','live_audio_import_apply','live_project_import','live_device_duplicate_preview','live_device_duplicate_apply','live_audio_clip_preview','live_audio_clip_apply','live_note_edit_preview','live_note_edit_apply','live_mixer_preview','live_mixer_apply','live_view_preview','live_view_apply','live_locator_jump_preview','live_locator_jump_apply','live_browser_load_preview','live_browser_load_apply','live_clip_move_preview','live_clip_move_apply','live_arrangement_clip_preview','live_arrangement_clip_apply','live_recording_preview','live_recording_apply','live_realtime_arm_preview','live_realtime_arm_apply','live_realtime_disarm','live_realtime_stats','live_browser_search','live_render_offline','live_clip_duplicate_preview','live_clip_duplicate_apply','live_routing_preview','live_routing_apply','live_capture_midi_preview','live_capture_midi_apply','live_scene_capture_preview','live_scene_capture_apply','live_status','live_snapshot','live_discover','live_note_read','live_song_state','live_performance_read','live_data_read','live_device_read','live_browser_roots','live_browser_inspect','live_automation_read','live_message','live_observe_poll','live_subscribe','live_unsubscribe','live_tempo_preview','live_tempo_apply','live_session_structure_preview','live_session_structure_apply','live_device_parameter_preview','live_device_parameter_apply','live_object_rename_preview','live_object_rename_apply','live_arrangement_section_preview','live_arrangement_section_apply','live_undo','live_transaction_release','live_recovery_finalize','live_undo_step_begin','live_undo_step_end','live_song_undo','live_song_redo','live_change'];
for(const modern of [false,true])for(const tool of tools)for(const args of [null,{},[],{extra:true}])await run('validation',[{tool,args}],{modern});
for(const modern of [false,true])for(const sync of [false,true])await run('tempo',[{tool:'live_tempo_preview',args:{tempo:130}},{tool:'live_tempo_apply',args:{transactionId:'$tx',confirmation:'apply',idempotencyKey:'apply-key'}},{tool:'live_undo',args:{transactionId:'$tx',confirmation:'undo',idempotencyKey:'undo-key'}},{tool:'live_transaction_release',args:{transactionIds:['$tx']}}],{modern,sync});
for(const modern of [false,true])await run('fused-tempo',[{tool:'live_change',args:{tool:'live_tempo_preview',args:{tempo:135},idempotencyKey:'fused-key'}},{tool:'live_change',args:{tool:'live_tempo_preview',args:{tempo:135},idempotencyKey:'fused-key'}},{tool:'live_change',args:{tool:'live_tempo_preview',args:{tempo:136},idempotencyKey:'fused-key'}},{tool:'live_undo',args:{transactionId:'$tx',confirmation:'undo',idempotencyKey:'undo-key'}}],{modern});
for(const tool of ['live_session_audition_preview','live_clip_launch_preview','live_audio_capture_preview','live_recording_preview','live_realtime_arm_preview','live_application_dialog_preview','live_fire_button_preview','live_missing_preview','wrong','live_change_preview'])await run('fused-rejection',[{tool:'live_change',args:{tool,args:{}}}]);
for(const args of [{tool:'live_tempo_preview',args:{tempo:20},idempotencyKey:'short'},{tool:'live_tempo_preview',args:{tempo:19}},{tool:'live_tempo_preview',args:[]},{tool:'live_tempo_preview',args:{tempo:125},extra:true},{tool:'live_tempo_preview',args:{tempo:999}}])await run('fused-input',[{tool:'live_change',args}]);
for(const types of [undefined,[],['transport'],['transport','transport'],['missing'],null,3])await run('subscriptions',[{tool:'live_subscribe',args:types===undefined?{}:{types}},{tool:'live_unsubscribe'}]);
await run('preabort',[{tool:'live_change',args:{tool:'live_tempo_preview',args:{tempo:130}},abort:true},{tool:'live_undo',abort:true},{tool:'live_status'}]);
await run('undo-policy',[{tool:'live_change',args:{tool:'live_tempo_preview',args:{tempo:140}}},{policy:{profile:'read-only'}},{tool:'live_undo',args:{transactionId:'$tx',confirmation:'undo',idempotencyKey:'undo-key'}}]);
for(const modern of [false,true])for(const fused of [false,true])for(const [name,args]of [
 ['track_structure',{action:'create-return',name:'Echo'}],['device_delete',{ref:'device:utility-1'}],['clip_delete',{clipRef:'clip:clip-1'}],['arrangement_midi_clip',{trackRef:'track:track-1',start:8,length:4,notes:[{pitch:60,start:0,duration:1}]}],['data',{key:'kumi.test',value:'kept text'}],['browser_load',{itemId:'audio_effects/Utility',trackRef:'track:track-1'}],['device_duplicate',{deviceRef:'device:utility-1'}],['device',{action:'insert',trackRef:'track:track-1',deviceName:'Utility'}],['mixer',{trackRef:'track:track-1',volume:0.5}]
])await run('production-mutation',[
 ...(fused?[{tool:'live_change',args:{tool:'live_'+name+'_preview',args,idempotencyKey:'change-key'}}]:[{tool:'live_'+name+'_preview',args},{tool:'live_'+name+'_apply',args:{transactionId:'$tx',confirmation:'apply',idempotencyKey:'apply-key'}}]),
 {tool:'live_undo',args:{transactionId:'$tx',confirmation:'undo',idempotencyKey:'undo-key'}}
],{modern});
const pool=[],seen=new Map(),intern=v=>{const k=JSON.stringify(v);if(!seen.has(k)){seen.set(k,pool.length);pool.push(v)}return seen.get(k)};
for(const c of cases){c.results=c.results.map(intern);c.state=intern(c.state)}
fs.writeFileSync(new URL('host-dispatch-oracle.json',import.meta.url),JSON.stringify({cases,pool}));
console.log(cases.length+' public dispatcher cases');
